function solve(n) {
  const len = 2 * n;
  const res = [];
  for (let mask = 0; mask < 1 << len; mask++) {
    let s = '';
    let balance = 0;
    let ok = true;
    for (let i = len - 1; i >= 0; i--) {
      if ((mask >> i) & 1) {
        s += '(';
        balance += 1;
      } else {
        s += ')';
        balance -= 1;
      }
      if (balance < 0) {
        ok = false;
        break;
      }
    }
    if (ok && balance === 0) res.push(s);
  }
  res.sort();
  return res;
}

function solve(n) {
  const res = [];
  const cur = [];
  const go = (open, close) => {
    if (cur.length === 2 * n) {
      res.push(cur.join(''));
      return;
    }
    if (open < n) {
      cur.push('(');
      go(open + 1, close);
      cur.pop();
    }
    if (close < open) {
      cur.push(')');
      go(open, close + 1);
      cur.pop();
    }
  };
  go(0, 0);
  res.sort();
  return res;
}
